#include <vector>

class Solution {
public:
    std::vector<bool> checkIfPrerequisite(int numCourses, std::vector<std::vector<int>>& prerequisites, std::vector<std::vector<int>>& queries) {
        std::vector<std::vector<bool>> reach(numCourses, std::vector<bool>(numCourses, false));
        for (const auto& p : prerequisites) reach[p[0]][p[1]] = true;
        for (int k = 0; k < numCourses; ++k) {
            for (int i = 0; i < numCourses; ++i) {
                for (int j = 0; j < numCourses; ++j) {
                    if (reach[i][k] && reach[k][j]) reach[i][j] = true;
                }
            }
        }
        std::vector<bool> res;
        for (const auto& q : queries) res.push_back(reach[q[0]][q[1]]);
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Boolean> checkIfPrerequisite(int numCourses, int[][] prerequisites, int[][] queries) {
        boolean[][] reach = new boolean[numCourses][numCourses];
        for (int[] p : prerequisites) reach[p[0]][p[1]] = true;
        for (int k = 0; k < numCourses; k++) {
            for (int i = 0; i < numCourses; i++) {
                for (int j = 0; j < numCourses; j++) {
                    if (reach[i][k] && reach[k][j]) reach[i][j] = true;
                }
            }
        }
        List<Boolean> res = new ArrayList<>();
        for (int[] q : queries) res.add(reach[q[0]][q[1]]);
        return res;
    }
}

var checkIfPrerequisite = function(numCourses, prerequisites, queries) {
    const reach = Array.from({ length: numCourses }, () => new Array(numCourses).fill(false));
    for (const [u, v] of prerequisites) reach[u][v] = true;
    for (let k = 0; k < numCourses; k++) {
        for (let i = 0; i < numCourses; i++) {
            for (let j = 0; j < numCourses; j++) {
                if (reach[i][k] && reach[k][j]) reach[i][j] = true;
            }
        }
    }
    return queries.map(([u, v]) => reach[u][v]);
};
